diff --git a/src/api/worker/facades/EntropyFacade.ts b/src/api/worker/facades/EntropyFacade.ts
new file mode 100644
index 000000000..ed675e37e
--- /dev/null
+++ b/src/api/worker/facades/EntropyFacade.ts
@@ -0,0 +1,106 @@
+import type { EntropySource } from "@tutao/tutanota-crypto"
+import { aes128Decrypt, random } from "@tutao/tutanota-crypto"
+import { assertWorkerOrNode } from "../../common/Env"
+import { neverNull, noOp, ofClass } from "@tutao/tutanota-utils"
+import { UserFacade } from "./UserFacade"
+import { IServiceExecutor } from "../../common/ServiceRequest"
+import { EntityClient } from "../../common/EntityClient"
+import { createEntropyData, TutanotaPropertiesTypeRef } from "../../entities/tutanota/TypeRefs.js"
+import { EntropyService } from "../../entities/tutanota/Services"
+import { CryptoError } from "../../common/error/CryptoError"
+import { ConnectionError, LockedError, ServiceUnavailableError } from "../../common/error/RestError"
+import { encryptBytes } from "../crypto/CryptoFacade"
+
+assertWorkerOrNode()
+
+/** A chunk of entropy collected from a single source. */
+export type EntropyDataChunk = {
+	source: EntropySource
+	entropy: number
+	data: number | Array<number>
+}
+
+// The amount of collected entropy (in bit) and the minimal time in between two updates of the
+// stored entropy which both have to be exceeded before the entropy is persisted to the server again.
+const REQUIRED_ENTROPY_FOR_STORING = 5000
+const STORE_ENTROPY_INTERVAL_MS = 1000 * 60 * 5
+
+/**
+ * Centralizes all entropy related operations: adding freshly collected entropy to the randomizer as well as
+ * loading and persisting the entropy of the currently logged in user. Keeping this logic in a single place
+ * decouples the entropy management from the WorkerImpl and the LoginFacade.
+ */
+export class EntropyFacade {
+	// the amount of new entropy (in bit) collected since the last time the entropy was stored on the server
+	private newEntropy: number = -1
+	private lastEntropyUpdate: number = Date.now()
+
+	constructor(
+		private readonly userFacade: UserFacade,
+		private readonly serviceExecutor: IServiceExecutor,
+		private readonly entityClient: EntityClient,
+	) {}
+
+	/**
+	 * Adds entropy to the randomizer. Stores the entropy for a user when enough entropy has been collected.
+	 * @param entropy
+	 * @returns {Promise.<void>}
+	 */
+	addEntropy(entropy: EntropyDataChunk[]): Promise<void> {
+		try {
+			return random.addEntropy(entropy)
+		} finally {
+			this.newEntropy = this.newEntropy + entropy.reduce((sum, value) => value.entropy + sum, 0)
+			const now = Date.now()
+
+			if (this.newEntropy > REQUIRED_ENTROPY_FOR_STORING && now - this.lastEntropyUpdate > STORE_ENTROPY_INTERVAL_MS) {
+				this.lastEntropyUpdate = now
+				this.newEntropy = 0
+				this.storeEntropy()
+			}
+		}
+	}
+
+	/**
+	 * Loads the entropy of the last logout from the server and feeds it to the randomizer.
+	 */
+	loadEntropy(): Promise<void> {
+		return this.entityClient.loadRoot(TutanotaPropertiesTypeRef, this.userFacade.getUserGroupId()).then((tutanotaProperties) => {
+			if (tutanotaProperties.groupEncEntropy) {
+				try {
+					let entropy = aes128Decrypt(this.userFacade.getUserGroupKey(), neverNull(tutanotaProperties.groupEncEntropy))
+					random.addStaticEntropy(entropy)
+				} catch (error) {
+					if (error instanceof CryptoError) {
+						console.log("could not decrypt entropy", error)
+					}
+				}
+			}
+		})
+	}
+
+	/**
+	 * Persists freshly generated entropy to the server so that it can be used again after the next login.
+	 */
+	storeEntropy(): Promise<void> {
+		// We only store entropy to the server if we are the leader
+		if (!this.userFacade.isFullyLoggedIn() || !this.userFacade.isLeader()) return Promise.resolve()
+		const userGroupKey = this.userFacade.getUserGroupKey()
+		const entropyData = createEntropyData({
+			groupEncEntropy: encryptBytes(userGroupKey, random.generateRandomData(32)),
+		})
+		return this.serviceExecutor
+			.put(EntropyService, entropyData)
+			.catch(ofClass(LockedError, noOp))
+			.catch(
+				ofClass(ConnectionError, (e) => {
+					console.log("could not store entropy", e)
+				}),
+			)
+			.catch(
+				ofClass(ServiceUnavailableError, (e) => {
+					console.log("could not store entropy", e)
+				}),
+			)
+	}
+}
