+
+/**
+ * Remove technical fields from the entity and all of its nested objects.
+ *
+ * Technical fields are added to entities for internal purposes (e.g. keeping the encrypted value of a final field around)
+ * and should not be persisted or carried over when an entity is cloned.
+ */
+export function removeTechnicalFields<T extends SomeEntity>(entity: T) {
+	// _finalEncrypted fields are kept on the entity to be able to write them back but they should not be persisted or leak to the copies.
+	function _removeTechnicalFields(erased: Record<string, any>) {
+		for (const key of Object.keys(erased)) {
+			if (key.startsWith("_finalEncrypted")) {
+				delete erased[key]
+			} else {
+				const value = erased[key]
+				if (value instanceof Object) {
+					_removeTechnicalFields(value)
+				}
+			}
+		}
+	}
+
+	_removeTechnicalFields(entity)
+}
